/* =====================================================================
   data/lessons.js — محتوى جميع الدروس (كتاب التقنية الرقمية ٢)
   =====================================================================

   📌 دليل سريع للمعلمة (بدون حاجة لمعرفة البرمجة):

   • كل درس مكتوب بهذا الشكل:
       addLesson('u1', {               ← رمز الوحدة
         id: 'u1l1',                   ← رمز الدرس (يظهر في الرابط)
         title: 'اسم الدرس',
         page: 11,                     ← رقم الصفحة في الكتاب
         slides: [ ...الشرائح... ]
       });

   • كل شريحة بين قوسين { } ويفصل بينها فاصلة ,
     وأهم خانة فيها هي type (نوع الشريحة).

   • لتعديل سؤال: ابحثي عن نص السؤال (Ctrl + F) وغيّري الكلمات
     بين علامتي التنصيص ' ' فقط، واحذري حذف الفواصل أو الأقواس.

   • لإضافة سؤال اختيار من متعدد: انسخي هذا السطر والصقيه بين شريحتين:
       { type: 'mcq', question: 'نص السؤال؟', options: ['خيار ١', 'خيار ٢', 'خيار ٣', 'خيار ٤'], answer: 2, explain: 'سبب الإجابة' },
     answer = رقم الخيار الصحيح (١ هو الأول، ٢ هو الثاني ...).

   • لإضافة عبارة صح أم خطأ: داخل items في شريحة tf أضيفي:
       { text: 'العبارة', answer: 'صح' },     أو    answer: 'خطأ'

   • لكتابة كلمة بخط غامق ضعيها بين نجمتين مزدوجتين: **كلمة**
   • للانتقال لسطر جديد داخل النص اكتبي: \n

   • أنواع الشرائح المتاحة:
     welcome    الترحيب (يُكمل تلقائيًا باسم الدرس والمعلمة والمدرسة)
     warmup     تحضير: قرعة + مراجعة          questions: [{q, a}]
     objectives أهداف الدرس                    items: ['هدف', ...]
     hook / story / predict  تمهيد / قصة / ماذا تتوقعين؟   emoji, story, question, answer
     points     لاحظي واكتشفي (بطاقات)          items: [{icon, title, text}], reveal: true لإخفائها حتى الضغط
     flip       بطاقات تنقلب بالضغط             cards: [{icon, front, back}]
     compare    جدول مقارنة                     headers: [], rows: [[...], ...]
     steps      خطوات تُكشف بالتتابع            items: ['خطوة', ...]
     code       كود مع معاينة                   code, lang ('html' | 'css' | 'js'), preview
     brainstorm عصف ذهني                        question, ideas: [...]
     tps        فكّري – زاوجي – شاركي            question, think, pair, share (بالثواني), answer
     coop       تعلّم تعاوني للمجموعات          groups: [{name, task}], seconds
     mcq        اختيار من متعدد                 question, options, answer, explain
     tf         صح أم خطأ                        items: [{text, answer, explain}]
     sort       تصنيف بالسحب والإفلات           categories: [...], items: [{text, cat}]
     order      ترتيب بالسحب                    items: [...] (بالترتيب الصحيح، وسيُخلط تلقائيًا)
     challenge  تحدّي الدقيقة                   seconds, items: [{q, a}]
     review     مراجعة وتلخيص                   items: [{icon, title, text}]
     closing    ختام تحفيزي                     emoji, title, message

   • استراتيجيات إضافية:
     match      صِلي وطابقي                     labels: ['عنوان١','عنوان٢'], pairs: [{a, b}]
     wheel      عجلة الأسئلة                    icon, items: [{q, a}]
     boxes      الصناديق الغامضة                icon, items: [{q, a}] أو {bonus: 'مفاجأة'}
     teams      مسابقة الفريقين بلوحة نقاط      teams: ['فريق١','فريق٢'], items: [{q, a}]
     fill       أكملي الفراغ                     text: 'جملة فيها [[الكلمة]] المطلوبة', extras: [كلمات تمويه]
     exit       بطاقة الخروج ٣-٢-١               seconds (اختياري)
     vscode     محاكي VS Code للبرمجة           task, files: [{name, code}], checks: [{test, msg, file}], hint, solution, devices

   • ثيم كل وحدة يُحدَّد تلقائيًا من رمزها (u1 … u5)، ويظهر اسمه من themeName.

   • خانات اختيارية لأي شريحة: title (العنوان)، tag (الوسم أعلى العنوان)،
     subtitle (سطر توضيحي)، transition ('fade' | 'slide' | 'zoom').

   • أي تعديل هنا يظهر مباشرة في العرض بعد تحديث الصفحة (F5).
   ===================================================================== */

window.LESSONS_DATA = {
  book: {
    title: 'التقنية الرقمية ٢',
    subject: 'التقنية الرقمية ٢',
    grade: 'السنة الثانية — التعليم الثانوي (نظام المسارات)',
    edition: 'طبعة ١٤٤٨ هـ / ٢٠٢٦ م'
  },
  units: [
    { id: 'u1', themeName: '🔬 مختبر البيانات', icon: '📊', title: 'الوحدة الأولى: علم البيانات', subtitle: 'البيانات والمعلومات والمعرفة، التحقق من البيانات، والتنبؤ والتشفير في إكسل', lessons: [] },
    { id: 'u2', themeName: '🧠 عالم الذكاء', icon: '🤖', title: 'الوحدة الثانية: الذكاء الاصطناعي', subtitle: 'التحول الرقمي، تعلّم الآلة، وبرمجة الذكاء الاصطناعي بسكراتش', lessons: [] },
    { id: 'u3', themeName: '🎨 استوديو التصميم', icon: '🎨', title: 'الوحدة الثالثة: التصميم الرسومي', subtitle: 'مبادئ التصميم، الملصق الإعلاني في إنكسكيب، والإعلانات المتحركة في جمب', lessons: [] },
    { id: 'u4', themeName: '📣 وكالة التسويق', icon: '📣', title: 'الوحدة الرابعة: التسويق الإلكتروني', subtitle: 'مفهوم التسويق الإلكتروني، والتسويق والحملات عبر البريد الإلكتروني', lessons: [] },
    { id: 'u5', themeName: '💻 مختبر البرمجة', icon: '🌐', title: 'الوحدة الخامسة: البرمجة المتقدمة باستخدام HTML', subtitle: 'HTML و CSS والتصميم المستجيب وجافا سكريبت والرسائل الإخبارية الرقمية', lessons: [] }
  ]
};

/* دالة إضافة درس إلى وحدته (لا تحتاجين لتعديلها) */
function addLesson(unitId, lesson) {
  var u = window.LESSONS_DATA.units.find(function (x) { return x.id === unitId; });
  if (u) u.lessons.push(lesson);
}


